// "Amanhã" no fuso de São Paulo, convertido para UTC para consultar o banco.
const amanha = $now.setZone('America/Sao_Paulo').plus({ days: 1 }).startOf('day');
return [{
  json: {
    inicio_utc: amanha.toUTC().toISO(),
    fim_utc: amanha.plus({ days: 1 }).toUTC().toISO(),
    data_label: amanha.toFormat('dd/MM/yyyy')
  }
}];

// Uma linha por instalação. Se não houver nenhuma, registra isso (não fica em silêncio).
const { data_label } = $('Calcular amanhã').first().json;
const agora = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });
const hora = (iso) => new Date(iso).toLocaleTimeString('pt-BR', { timeZone: 'America/Sao_Paulo', hour: '2-digit', minute: '2-digit' });

const instalacoes = $input.all().filter((i) => i.json.id);

if (instalacoes.length === 0) {
  return [{
    json: {
      executado_em: agora,
      data_instalacao: data_label,
      horario: '',
      pedido: '',
      cliente: 'Nenhuma instalação agendada para amanhã',
      endereco: '',
      tecnico: '',
      telefone_cliente: ''
    }
  }];
}

return instalacoes.map((i) => ({
  json: {
    executado_em: agora,
    data_instalacao: data_label,
    horario: hora(i.json.data_instalacao),
    pedido: i.json.numero,
    cliente: i.json.cliente_nome,
    endereco: [i.json.cliente_endereco, i.json.cliente_bairro, i.json.cliente_cidade].filter(Boolean).join(', '),
    tecnico: i.json.tecnico_nome,
    telefone_cliente: i.json.cliente_telefone
  }
}));
